solution.solution.js:
function titleCase(text) {
  return text.split(" ").map(w => w ? w[0].toUpperCase() + w.slice(1) : w).join(" ");
}

function truncate(text, max) {
  return text.length <= max ? text : text.slice(0, max - 1) + "…";
}

function countChars(text) {
  return [...text].length;
}

function receiptLine(item, price) {
  return item.padEnd(12) + price.toFixed(2).padStart(8);
}

unitTests:
test("title case", () => {
  checkEq(titleCase("the lord of the rings"), "The Lord Of The Rings");
  checkEq(titleCase("a"), "A");
  checkEq(titleCase(""), "");
});

test("truncate", () => {
  checkEq(truncate("Hello, world", 6), "Hello…");
  checkEq(truncate("short", 10), "short");
  checkEq(truncate("exact", 5), "exact");
});

test("characters", () => {
  checkEq(countChars("hi 😀"), 4);
  checkEq(countChars("café"), 4);
  checkEq(countChars(""), 0);
});

test("receipt lines", () => {
  checkEq(receiptLine("tea", 2.5), "tea             2.50");
  checkEq(receiptLine("chocolate cake", 12), "chocolate cake   12.00");
});

